```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const session = require('express-session');
const bodyParser = require('body-parser');

const app = express();
const PORT = 3000;

// In-memory user store (replace with a database in production)
const users = {};

app.use(bodyParser.urlencoded({ extended: true }));

app.use(session({
  secret: 'your-secret-key', // Replace with a strong secret in production
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false } // Set to true if using HTTPS
}));

// Registration endpoint
app.post('/register', async (req, res) => {
  const { username, password } = req.body;
  if (users[username]) {
    return res.status(400).send('User already exists');
  }
  try {
    const hashedPassword = await bcrypt.hash(password, 10);
    users[username] = { password: hashedPassword };
    res.status(201).send('User registered successfully');
  } catch (err) {
    res.status(500).send('Error registering user');
  }
});

// Login endpoint
app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  const user = users[username];
  if (!user) {
    return res.status(400).send('Invalid username or password');
  }
  try {
    const match = await bcrypt.compare(password, user.password);
    if (match) {
      req.session.user = username;
      res.send('Login successful');
    } else {
      res.status(400).send('Invalid username or password');
    }
  } catch (err) {
    res.status(500).send('Error during login');
  }
});

// Middleware to protect routes
function authMiddleware(req, res, next) {
  if (req.session.user) {
    next();
  } else {
    res.status(401).send('Unauthorized');
  }
}

// Example protected route
app.get('/dashboard', authMiddleware, (req, res) => {
  res.send(`Welcome ${req.session.user} to your dashboard`);
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

This code snippet demonstrates:

- Secure password hashing with bcrypt.
- Basic session management with express-session.
- User registration and login endpoints.
- Middleware to protect routes that require authentication.

For production, consider using HTTPS, a persistent database, environment variables for secrets, and additional security measures like rate limiting and input validation.

