```javascript
// Function to generate a cryptographic key
async function generateKey() {
  return await crypto.subtle.generateKey(
    {
      name: "AES-GCM",
      length: 256,
    },
    true, // extractable
    ["encrypt", "decrypt"]
  );
}

// Function to encrypt data
async function encryptData(key, data) {
  const encoder = new TextEncoder();
  const encodedData = encoder.encode(data);
  const iv = crypto.getRandomValues(new Uint8Array(12)); // Initialization vector

  const encrypted = await crypto.subtle.encrypt(
    {
      name: "AES-GCM",
      iv: iv,
    },
    key,
    encodedData
  );

  // Return iv and encrypted data as base64 strings for storage/transmission
  return {
    iv: btoa(String.fromCharCode(...iv)),
    encryptedData: btoa(String.fromCharCode(...new Uint8Array(encrypted))),
  };
}

// Function to decrypt data
async function decryptData(key, ivBase64, encryptedDataBase64) {
  const iv = Uint8Array.from(atob(ivBase64), c => c.charCodeAt(0));
  const encryptedData = Uint8Array.from(atob(encryptedDataBase64), c => c.charCodeAt(0));

  const decrypted = await crypto.subtle.decrypt(
    {
      name: "AES-GCM",
      iv: iv,
    },
    key,
    encryptedData
  );

  const decoder = new TextDecoder();
  return decoder.decode(decrypted);
}

// Example usage:
(async () => {
  const key = await generateKey();
  const data = "Sensitive user data";

  const encrypted = await encryptData(key, data);
  console.log("Encrypted:", encrypted);

  const decrypted = await decryptData(key, encrypted.iv, encrypted.encryptedData);
  console.log("Decrypted:", decrypted);
})();
```

